// GENERATED RUNTIME — copied verbatim by Kogent into agents/<name>/runtime/. Do not edit: edit the spec.
// instructions.md: one escaped line per value, one marker per instruction (§5.4). The model never sees ids.
export interface InstructionsDoc { name: string; role: string; voice: string; instructions: Array<{ id: string; text: string }> }

const HEADER = '<!-- GENERATED by Kogent from the agent spec. Do not edit: edit the spec and rebuild. -->'
const MARKER = / <!-- (IN-[1-9]\d*) -->$/

// Escape so every value is one line and can't forge a marker or a heading.
const esc = (s: string) => s.replace(/\\/g, '\\\\').replace(/\r?\n/g, '\\n').replace(/<!--/g, '<\\!--').replace(/-->/g, '--\\>')
const unesc = (s: string) => s.replace(/\\(\\|n|!|>)/g, (_m, c: string) => (c === 'n' ? '\n' : c === '\\' ? '\\' : c))

export function renderInstructionsMd(doc: InstructionsDoc): string {
  return [
    HEADER, `# ${esc(doc.name)}`, '', '## Role', esc(doc.role), '', '## Voice', esc(doc.voice), '', '## Instructions',
    ...doc.instructions.map((i) => `- ${esc(i.text)} <!-- ${i.id} -->`), '',
  ].join('\n')
}

export function parseInstructionsMd(md: string): InstructionsDoc {
  const lines = md.split(/\r?\n/)
  const at = (h: string, from: number) => { const i = lines.indexOf(h, from); if (i < 0) throw new Error(`instructions.md: missing ${h}`); return i }
  const name = unesc(lines.find((l) => l.startsWith('# '))!.slice(2))
  const roleAt = at('## Role', 0) + 1
  const voiceHead = at('## Voice', roleAt + 1)
  const instrHead = at('## Instructions', voiceHead + 2)
  const role = unesc(lines[roleAt])
  const voice = unesc(lines[voiceHead + 1])
  const instructions = lines.slice(instrHead + 1).filter((l) => l.startsWith('- ')).map((l) => {
    const m = l.match(MARKER)
    if (!m) throw new Error(`instructions.md: an instruction line has no marker: ${l}`)
    return { id: m[1], text: unesc(l.slice(2, l.length - m[0].length)) }
  })
  return { name, role, voice, instructions }
}

const TEMPLATE_HEADER = /^<!-- GENERATED by Kogent from the agent spec \(shape-[1-9]\d*\)\. Do not edit: edit the spec and rebuild\. -->\r?\n/
/** templates/<shape-id>.md without its generated header (P4-R45). */
export function templateBody(md: string): string { return md.replace(TEMPLATE_HEADER, '').replace(/\s+$/, '') }

export function composeInstructions(md: string, opts: { without?: string[]; template?: { name: string; text: string } } = {}): string {
  const doc = parseInstructionsMd(md)
  const drop = new Set(opts.without ?? [])
  for (const id of drop) if (!doc.instructions.some((i) => i.id === id)) throw new Error(`instructions.md has no instruction ${id}`)
  const kept = doc.instructions.filter((i) => !drop.has(i.id))
  const base = `${doc.role}\n\nVoice: ${doc.voice}\n\nFollow these instructions:\n${kept.map((i) => `- ${i.text}`).join('\n')}`
  // Agent specs §4.1/§5.4 rev 7: the template is part of the agent; a without-run removes one instruction and keeps it.
  return opts.template ? `${base}\n\nWrite every ${opts.template.name} following this template:\n${opts.template.text}` : base
}
